let guideStep=0;const guide=$('#guide');guide.classList.add('forma-guide');guide.setAttribute('aria-labelledby','guideHeading');
function guideDemo(kind){const card='<div class="tour-mini-card"><span>NOTE</span><strong>A clear plan</strong><i></i><i></i></div>';if(kind==='draw')return '<svg class="tour-sketch" viewBox="0 0 300 140"><path d="M50 94Q60 30 115 63T208 60Q240 65 254 95"/><path d="M45 115h220"/></svg>';if(kind==='connect')return '<div class="tour-connected">'+card+'<span class="tour-wire">⌁</span>'+card+'</div>';if(kind==='lock')return card+'<div class="tour-lock">'+lockIcon+'</div>';if(kind==='save')return '<div class="tour-file"><span>FORMA</span><strong>My board</strong><small>Board backup</small></div>';if(kind==='group')return '<div class="tour-group">'+card+card+'<b class="tour-handle"></b></div>';return '<div class="tour-simple">'+card+'<div class="tour-action">'+({create:'＋',edit:'B &nbsp; <i>I</i> &nbsp; <u>U</u>',navigate:'− &nbsp; 100% &nbsp; ＋'}[kind]||'')+'</div></div>'}
function renderGuide(){const s=guideSteps[guideStep];guide.innerHTML=`<div class="tour-header"><div><span class="tour-brand">forma</span><span class="tour-guide-label">Getting started</span></div><button class="tour-close" aria-label="Close tutorial">×</button></div><div class="tour-layout"><nav class="tour-topics" aria-label="Tutorial steps">${guideSteps.map((s,i)=>`<button data-guide-step="${i}" aria-current="${i===guideStep?'step':'false'}"><span>${String(i+1).padStart(2,'0')}</span>${s.title}</button>`).join('')}</nav><div class="tour-content"><div class="tour-step">${s.tag} <span>${guideStep+1} / ${guideSteps.length}</span></div><div class="tour-demo" aria-hidden="true">${guideDemo(s.demo)}</div><h2 id="guideHeading" tabindex="-1">${s.title}</h2><p class="tour-intro">${s.text}</p><ol class="tour-actions">${s.actions.map(t=>'<li>'+t+'</li>').join('')}</ol></div></div><div class="tour-footer"><div class="tour-progress" aria-label="Step ${guideStep+1} of ${guideSteps.length}">${guideSteps.map((_,i)=>`<span class="${i<=guideStep?'visited':''}"></span>`).join('')}</div><div><button id="guideBack" ${guideStep===0?'disabled':''}>Back</button><button id="guideNext" class="tour-next">${guideStep===guideSteps.length-1?'Start creating':'Next step'} <span>→</span></button></div></div>`;guide.querySelector('.tour-close').onclick=()=>guide.close();guide.querySelectorAll('[data-guide-step]').forEach(b=>b.onclick=()=>changeGuide(Number(b.dataset.guideStep)));$('#guideBack').onclick=()=>changeGuide(guideStep-1);$('#guideNext').onclick=()=>{if(guideStep===guideSteps.length-1)guide.close();else changeGuide(guideStep+1)}}
function changeGuide(index){guideStep=Math.max(0,Math.min(guideSteps.length-1,index));renderGuide();$('#guideHeading').focus()}
renderGuide();$('#help').innerHTML='ⓘ <span>Forma guide</span><kbd>?</kbd>';$('#help').onclick=()=>{guideStep=0;renderGuide();guide.showModal()};guide.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();changeGuide(guideStep+1)}if(e.key==='ArrowLeft'){e.preventDefault();changeGuide(guideStep-1)}});

// Duplicate the whole selection as one layout into nearby unoccupied space.
function itemRect(n){const el=document.querySelector(`[data-id="${n.id}"]`);return{x:n.x,y:n.y,w:n.w,h:el?.offsetHeight||n.h||300}}
function rectsOverlap(a,b,gap=48){return a.x<b.x+b.w+gap&&a.x+a.w+gap>b.x&&a.y<b.y+b.h+gap&&a.y+a.h+gap>b.y}
function duplicatePlacement(nodes){const source=nodes.map(itemRect),occupied=board().nodes.map(itemRect),left=Math.min(...source.map(r=>r.x)),top=Math.min(...source.map(r=>r.y)),right=Math.max(...source.map(r=>r.x+r.w)),bottom=Math.max(...source.map(r=>r.y+r.h)),w=right-left,h=bottom-top,stepX=w+64,stepY=h+64,v=board().view,r=$('#canvas').getBoundingClientRect();function free(dx,dy){return !source.some(a=>occupied.some(b=>rectsOverlap({...a,x:a.x+dx,y:a.y+dy},b)))}for(let ring=1;ring<250;ring++){const choices=[];for(let i=-ring;i<=ring;i++)for(let j=-ring;j<=ring;j++)if(Math.max(Math.abs(i),Math.abs(j))===ring){const dx=i*stepX,dy=j*stepY,cx=(left+dx+w/2)*v.z+v.x,cy=(top+dy+h/2)*v.z+v.y,outside=Math.max(0,-cx,cx-r.width)+Math.max(0,-cy,cy-r.height);choices.push({dx,dy,score:Math.hypot(dx,dy)+outside*2})}choices.sort((a,b)=>a.score-b.score);for(const c of choices)if(free(c.dx,c.dy))return c}return{dx:0,dy:Math.max(...occupied.map(r=>r.y+r.h))-top+64}}
function revealItems(ids){const ns=board().nodes.filter(n=>ids.includes(n.id));if(!ns.length)return;const rs=ns.map(itemRect),x=Math.min(...rs.map(r=>r.x)),y=Math.min(...rs.map(r=>r.y)),w=Math.max(...rs.map(r=>r.x+r.w))-x,h=Math.max(...rs.map(r=>r.y+r.h))-y,v=board().view,r=$('#canvas').getBoundingClientRect();if(x*v.z+v.x>=24&&y*v.z+v.y>=24&&(x+w)*v.z+v.x<=r.width-24&&(y+h)*v.z+v.y<=r.height-24)return;const z=Math.max(.425,Math.min(v.z,(r.width-100)/w,(r.height-100)/h));animateView({z,x:r.width/2-(x+w/2)*z,y:r.height/2-(y+h/2)*z})}
function deleteItems(ids){ids=expandGroups(ids);if(board().nodes.some(n=>ids.includes(n.id)&&n.locked)){toast('Unlock the selected items before deleting');return false}if(!ids.length)return false;remember();const set=new Set(ids),b=board();b.nodes=b.nodes.filter(n=>!set.has(n.id));b.edges=b.edges.filter(e=>!set.has(e.from)&&!set.has(e.to));selectedCards.clear();selected=null;focusedCard=null;render();save();toast('Items deleted · Ctrl/⌘ Z to undo');return true}
document.addEventListener('keydown',e=>{if(!['Delete','Backspace'].includes(e.key)||selectedEdge||e.target.closest('input,textarea,[contenteditable]')||document.querySelector('dialog[open]'))return;const ids=selectionIds();if(ids.length){e.preventDefault();e.stopImmediatePropagation();deleteItems(ids)}},true);

