// Image clipboard data takes precedence over HTML and ordinary editor paste.
document.addEventListener('paste',e=>{if(document.querySelector('dialog[open]'))return;const data=e.clipboardData;if(!data)return;const files=[...data.items].filter(i=>i.kind==='file'&&i.type.startsWith('image/')).map(i=>i.getAsFile()).filter(Boolean);if(files.length){e.preventDefault();e.stopImmediatePropagation();if(liveEdit)finishLive();contextAddPoint=null;images(files);return}if(e.target.closest('input,textarea,[contenteditable]'))return;const html=data.getData('text/html'),text=data.getData('text/plain').trim();let urls=[];if(html){const template=document.createElement('template');template.innerHTML=html;urls=[...template.content.querySelectorAll('img')].map(i=>i.getAttribute('src')).filter(Boolean)}if(!urls.length&&/^https?:\/\/[^\s]+\.(png|jpe?g|webp|gif)(\?[^\s]*)?$/i.test(text))urls=[text];urls=urls.filter(u=>/^https?:\/\//i.test(u)||/^data:image\/(png|jpeg|webp|gif);base64,/i.test(u)).slice(0,20);if(!urls.length)return;e.preventDefault();e.stopImmediatePropagation();contextAddPoint=null;pasteImageUrls(urls)},true);
async function pasteImageUrls(urls){const files=[];for(const url of urls){try{const response=await fetch(url,{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error();const blob=await response.blob();if(!blob.type.startsWith('image/')||blob.size>25*1024*1024)throw Error();files.push(new File([blob],'Pasted image.'+(blob.type.split('/')[1]||'png'),{type:blob.type}))}catch{toast('This site blocks image links. Right-click the image → Copy image, then paste again.')}}if(files.length)await images(files)}

