const projectsHeader=document.createElement('div');projectsHeader.className='projects-header';projectsHeader.innerHTML='<span>Projects</span><button id="createProject" title="Create project folder" aria-label="Create project folder">+</button>';$('#boards').before(projectsHeader);
const projectDialog=document.createElement('dialog');projectDialog.id='projectDialog';projectDialog.innerHTML='<form id="projectForm"><div class="dialog-top"><h2 id="projectHeading">Create project</h2><button type="button" class="close" aria-label="Close project">×</button></div><label>Project name<input id="projectName" required maxlength="60" placeholder="For example: Study plan"></label><div class="project-dialog-actions"><button type="button" id="removeProject">Remove folder</button><button type="button" id="cancelProject">Cancel</button><button type="submit" class="primary" id="saveProject">Create project</button></div></form>';document.body.append(projectDialog);let editingProject=null;
function openProjectEditor(id=null){editingProject=id;const folder=state.folders?.find(f=>f.id===id);$('#projectHeading').textContent=folder?'Edit project':'Create project';$('#projectName').value=folder?.title||'';$('#removeProject').hidden=!folder;$('#saveProject').textContent=folder?'Save changes':'Create project';$('#saveProject').dataset.tooltip=folder?'Save project name':'Create project folder';projectDialog.showModal();$('#projectName').focus()}
$('#createProject').onclick=()=>openProjectEditor();$('#cancelProject').onclick=()=>projectDialog.close();projectDialog.querySelector('.close').onclick=()=>projectDialog.close();$('#projectForm').onsubmit=e=>{e.preventDefault();const title=$('#projectName').value.trim();if(!title)return;remember();state.folders||=[];const folder=state.folders.find(f=>f.id===editingProject);if(folder)folder.title=title;else state.folders.push({id:uid(),title,collapsed:false});projectDialog.close();renderProjectSidebar();save()};function removeProjectFolder(id){remember();state.folders=state.folders.filter(f=>f.id!==id);for(const b of state.boards)if(b.folderId===id)delete b.folderId;if(projectDialog.open)projectDialog.close();renderProjectSidebar();save();toast('Folder removed · Boards kept · Undo available')}
