function boardMemberBadge(b){const count=b.cloud?(Number.isInteger(b.cloud.memberCount)?b.cloud.memberCount:null):1;return `<span class="board-members" title="${count===null?'Sharing count not loaded':b.cloud?count+' people with access':'Local board · Only you'}">${peopleIcon}<small>${count===null?'—':count>=10?'10+':count}</small></span>`}
function decorateBoardRow(row,b){row.classList.toggle('board-multi-selected',selectedBoardIds.has(b.id));row.draggable=false;row.querySelector('.board-members')?.remove();const label=row.querySelector('.board-select span');label.classList.add('board-name');label.insertAdjacentHTML('afterend',boardMemberBadge(b))}

function moveBoardsToProject(ids,folderId){ids=[...new Set(ids)].filter(id=>state.boards.some(b=>b.id===id));if(!ids.length)return;remember();for(const b of state.boards)if(ids.includes(b.id)){if(folderId)b.folderId=folderId;else delete b.folderId}const folder=state.folders?.find(f=>f.id===folderId);if(folder)folder.collapsed=false;selectedBoardIds=new Set(ids);renderProjectSidebar();save();toast(ids.length+' board'+(ids.length===1?'':'s')+(folderId?' moved to project':' moved out of project'))}
let sidebarDrag=null;const boardDragBadge=document.createElement('div');boardDragBadge.id='boardDragBadge';boardDragBadge.hidden=true;document.body.append(boardDragBadge);
function finishBoardDrag(e,cancel=false){const a=sidebarDrag;if(!a)return;sidebarDrag=null;boardDragBadge.hidden=true;document.querySelectorAll('.project-drop-hover').forEach(el=>el.classList.remove('project-drop-hover'));if(a.moved){lastBoardDrag=Date.now();if(!cancel&&a.target)moveBoardsToProject(a.ids,a.target.dataset.projectDrop==='root'?null:a.target.dataset.projectDrop)}if($('#boards').hasPointerCapture(a.pointerId))$('#boards').releasePointerCapture(a.pointerId)}
$('#boards').addEventListener('pointerdown',e=>{const row=e.target.closest('[data-board]');if(e.button!==0||!row||e.target.closest('[data-menu]'))return;sidebarDrag={sx:e.clientX,sy:e.clientY,pointerId:e.pointerId,ids:selectedBoardIds.has(row.dataset.board)?[...selectedBoardIds]:[row.dataset.board],moved:false,target:null}});
$('#boards').addEventListener('pointermove',e=>{const a=sidebarDrag;if(!a)return;if(!a.moved){if(Math.hypot(e.clientX-a.sx,e.clientY-a.sy)<5)return;a.moved=true;selectedBoardIds=new Set(a.ids);$('#boards').setPointerCapture(e.pointerId);document.querySelectorAll('.board-row').forEach(r=>r.classList.toggle('board-multi-selected',selectedBoardIds.has(r.dataset.board)));boardDragBadge.textContent=a.ids.length+' board'+(a.ids.length===1?'':'s');boardDragBadge.hidden=false}e.preventDefault();boardDragBadge.style.left=(e.clientX+14)+'px';boardDragBadge.style.top=(e.clientY+14)+'px';const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-project-drop]');if(a.target!==target){a.target?.classList.remove('project-drop-hover');target?.classList.add('project-drop-hover');a.target=target}});
$('#boards').addEventListener('pointerup',e=>finishBoardDrag(e));$('#boards').addEventListener('pointercancel',e=>finishBoardDrag(e,true));window.addEventListener('blur',()=>finishBoardDrag(null,true));document.addEventListener('keydown',e=>{if(e.key==='Escape')finishBoardDrag(e,true)});
function projectDropTarget(el,folderId){el.dataset.projectDrop=folderId||'root'}
function renderProjectSidebar(){if(!state)return;const nav=$('#boards'),rows=new Map([...nav.querySelectorAll('.board-row')].map(row=>[row.dataset.board,row]));if(!rows.size&&state.boards.some(b=>!!b.archived===showArchive)){// Rebuild rows without touching the canvas when only folder organization changes.
 const b=board();nav.innerHTML=state.boards.filter(x=>!!x.archived===showArchive).sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)).map(x=>`<div class="board-row ${x.id===b.id?'active':''}" data-board="${x.id}"><button class="board-select" data-open="${x.id}" title="${esc(x.title)}">${sidebarIcon(x.pinned?'pin':'board')}<span>${esc(x.title)}</span></button></div>`).join('');for(const row of nav.querySelectorAll('.board-row'))rows.set(row.dataset.board,row)}
 nav.replaceChildren();const root=document.createElement('div');root.className='project-root';root.textContent=showArchive?'Archived boards':'All boards';root.title='Drop here to move boards out of a project';projectDropTarget(root,null);nav.append(root);const folders=state.folders||[];for(const b of state.boards.filter(b=>!!b.archived===showArchive&&!folders.some(f=>f.id===b.folderId))){const row=rows.get(b.id);if(row){decorateBoardRow(row,b);nav.append(row)}}for(const folder of folders){const section=document.createElement('section');section.className='project-folder';const header=document.createElement('div');header.className='project-folder-heading';header.innerHTML=`<button data-folder-toggle="${folder.id}" aria-expanded="${!folder.collapsed}" data-tooltip="Click to expand or collapse · Right-click for project actions"><svg viewBox="0 0 24 24"><path d="M3 7h7l2-3h8v16H3z"/></svg><span>${esc(folder.title)}</span><small>${state.boards.filter(b=>b.folderId===folder.id&&!b.archived).length}</small></button>`;projectDropTarget(header,folder.id);section.append(header);const body=document.createElement('div');body.className='project-folder-boards';body.hidden=folder.collapsed;for(const b of state.boards.filter(b=>!!b.archived===showArchive&&b.folderId===folder.id)){const row=rows.get(b.id);if(row){decorateBoardRow(row,b);body.append(row)}}if(!body.children.length){const hint=document.createElement('div');hint.className='project-empty';hint.textContent='Drop boards here';projectDropTarget(hint,folder.id);body.append(hint)}section.append(body);nav.append(section)}document.querySelectorAll('.projects-header').forEach(el=>el.hidden=showArchive)}
const renderProjects=render;render=function(){renderProjects();renderProjectSidebar()};
const openSidebarBoard=$('#boards').onclick;
function paintBoardSelection(){document.querySelectorAll('.board-row').forEach(row=>row.classList.toggle('board-multi-selected',selectedBoardIds.has(row.dataset.board)))}
$('#boards').onclick=e=>{const toggle=e.target.closest('[data-folder-toggle]');if(Date.now()-lastBoardDrag<250)return;if(toggle){const folder=state.folders.find(f=>f.id===toggle.dataset.folderToggle);folder.collapsed=!folder.collapsed;renderProjectSidebar();save(false);return}const row=e.target.closest('[data-board]');if(!row)return;const id=row.dataset.board;if(e.shiftKey){e.preventDefault();const order=[...$('#boards').querySelectorAll('.board-row')].filter(row=>!row.closest('[hidden]')).map(row=>row.dataset.board),anchor=order.includes(boardSelectionAnchor)?boardSelectionAnchor:order.includes(state.active)?state.active:id,a=order.indexOf(anchor),b=order.indexOf(id);boardSelectionAnchor=anchor;selectedBoardIds=new Set(order.slice(Math.min(a,b),Math.max(a,b)+1));paintBoardSelection();return}if(e.ctrlKey||e.metaKey){e.preventDefault();if(selectedBoardIds.has(id))selectedBoardIds.delete(id);else selectedBoardIds.add(id);boardSelectionAnchor=id;paintBoardSelection();return}boardSelectionAnchor=id;selectedBoardIds=new Set([id]);openSidebarBoard(e)};


