// Outline icons and availability follow the actual meaningful history stack.
const preciseControls={undo:'<path d="M3 7v6h6"/><path d="M21 17a9 9 0 0 0-9-9 9 9 0 0 0-6 2.3L3 13"/>',redo:'<path d="M21 7v6h-6"/><path d="M3 17a9 9 0 0 1 9-9 9 9 0 0 1 6 2.3l3 2.7"/>',fit:'<path d="M8 3H5a2 2 0 0 0-2 2v3M21 8V5a2 2 0 0 0-2-2h-3M3 16v3a2 2 0 0 0 2 2h3M16 21h3a2 2 0 0 0 2-2v-3"/>'};for(const [id,path] of Object.entries(preciseControls))$('#'+id).innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true">'+path+'</svg>';
function historyAvailable(stack,current){for(let i=stack.length-1;i>=0;i--)if(historyFingerprint(readHistory(stack[i]))!==current)return true;return false}
function updateHistoryControls(){if(!state)return;const current=historyFingerprint(state);for(const [id,stack] of [['undo',history],['redo',future]]){const available=historyAvailable(stack,current);$('#'+id).disabled=!available;$('#'+id).setAttribute('aria-disabled',!available)}}
const renderControls=render;render=function(){renderControls();updateHistoryControls()};

// A single tooltip layer avoids overlapping browser tooltips.
const toolTip=document.createElement('div');toolTip.id='controlTooltip';toolTip.setAttribute('role','tooltip');toolTip.hidden=true;document.body.append(toolTip);let tooltipTarget=null;
const tooltipText={undo:'Undo · Ctrl+Z',redo:'Redo · Ctrl+Shift+Z',fit:'Zoom to fit · Ctrl+1',zoomLabel:'Zoom',drawPen:'Pen · P',eraseInk:'Eraser · E',searchBoard:'Search board · Ctrl+F',pan:'Move canvas',connect:'Connect cards',addMenuToggle:'Add card',collapseSidebar:'Toggle sidebar'};
for(const [id,label] of Object.entries(tooltipText)){const el=$('#'+id);el.dataset.tooltip=label;el.removeAttribute('title');el.setAttribute('aria-describedby','controlTooltip')}
function hideControlTooltip(){toolTip.hidden=true;tooltipTarget=null}
function showControlTooltip(el){if(!el?.dataset.tooltip)return;tooltipTarget=el;const tooltipHost=el.closest('dialog[open]')||document.body;if(toolTip.parentElement!==tooltipHost)tooltipHost.append(toolTip);toolTip.textContent=el.dataset.tooltip;toolTip.hidden=false;toolTip.classList.toggle('tooltip-side',!!el.closest('.toolbar'));toolTip.classList.toggle('tooltip-card',!!el.closest('.node'));const r=el.getBoundingClientRect(),w=toolTip.offsetWidth,h=toolTip.offsetHeight;let x=r.left+r.width/2-w/2,y=r.top-h-9;if(el.closest('.toolbar')){x=r.right+10;y=r.top+r.height/2-h/2}toolTip.style.left=Math.max(8,Math.min(innerWidth-w-8,x))+'px';toolTip.style.top=Math.max(8,Math.min(innerHeight-h-8,y))+'px'}
document.addEventListener('pointerover',e=>{if(drag?.moved||middlePan||inkStroke)return;const target=e.target.closest('[data-tooltip]');if(target&&target!==tooltipTarget)showControlTooltip(target)});document.addEventListener('pointerout',e=>{if(tooltipTarget&&!tooltipTarget.contains(e.relatedTarget))hideControlTooltip()});document.addEventListener('focusin',e=>{const target=e.target.closest('[data-tooltip]');if(target)showControlTooltip(target)});document.addEventListener('focusout',hideControlTooltip);document.addEventListener('pointerdown',hideControlTooltip);document.addEventListener('wheel',hideControlTooltip,{passive:true});window.addEventListener('resize',hideControlTooltip);

// Coalesce canvas movement; ink retains its own coalesced point samples.
let canvasMoveFrame=null,pendingCanvasMove=null;
const immediateCanvasMove=$('#canvas').onpointermove,immediateCanvasUp=$('#canvas').onpointerup,immediateCanvasCancel=$('#canvas').onpointercancel;
function flushCanvasMove(){if(canvasMoveFrame!==null)cancelAnimationFrame(canvasMoveFrame);canvasMoveFrame=null;const event=pendingCanvasMove;pendingCanvasMove=null;if(!event)return;immediateCanvasMove(event);if(edgeDrawFrame!==null){cancelAnimationFrame(edgeDrawFrame);edgeDrawFrame=null;drawEdgesNow();updateGroupBounds()}}
$('#canvas').onpointermove=e=>{if(inkStroke||erasing||middlePan||source){immediateCanvasMove(e);return}if(!drag&&!sizing&&!inkResize&&!marquee)return;pendingCanvasMove=e;if(canvasMoveFrame===null)canvasMoveFrame=requestAnimationFrame(flushCanvasMove)};
$('#canvas').onpointerup=e=>{flushCanvasMove();immediateCanvasUp(e)};
$('#canvas').onpointercancel=e=>{flushCanvasMove();immediateCanvasCancel?.(e)};
window.addEventListener('blur',()=>{if(canvasMoveFrame!==null)cancelAnimationFrame(canvasMoveFrame);canvasMoveFrame=null;pendingCanvasMove=null});

