const projectMenu=document.createElement('div');projectMenu.id='projectMenu';projectMenu.className='canvas-menu';projectMenu.setAttribute('role','menu');projectMenu.setAttribute('aria-label','Project actions');projectMenu.hidden=true;document.body.append(projectMenu);let contextProject=null;
