function openProjectMenu(id,x,y){const folder=state.folders?.find(f=>f.id===id);if(!folder)return;closeBoardMenu();closeCanvasMenus();contextProject=id;projectMenu.innerHTML='<button role="menuitem" data-project-action="edit" data-tooltip="Rename this project folder"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg><span>Edit project</span></button><button role="menuitem" data-project-action="remove" data-tooltip="Remove folder · Keep all boards · Undo available"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/></svg><span>Remove folder</span></button>';projectMenu.hidden=false;projectMenu.style.left=Math.max(8,Math.min(x,innerWidth-projectMenu.offsetWidth-8))+'px';projectMenu.style.top=Math.max(8,Math.min(y,innerHeight-projectMenu.offsetHeight-8))+'px';projectMenu.querySelector('button').focus()}
projectMenu.onclick=e=>{const action=e.target.closest('[data-project-action]')?.dataset.projectAction;if(!action)return;closeProjectMenu();if(action==='edit')openProjectEditor(contextProject);else removeProjectFolder(contextProject)};
